//! Sentinel's system junk plugin: the machine's own disposable data, as
//! opposed to any particular developer tool's.
//!
//! Three sources, and they do **not** earn their safety the same way. That is
//! the thing to understand before changing anything here.
//!
//! # 1. Thumbnail cache — safe by what it is
//!
//! `~/.cache/thumbnails/{normal,large,x-large,fail}`. Regenerated by the file
//! manager on demand, in a directory the platform designates for disposable
//! data. This is the ordinary shape every other Sentinel plugin has: constant
//! components joined onto a validated root.
//!
//! # 2. Trash — safe by what the user already decided
//!
//! `~/.local/share/Trash/{files,info,expunged}`. These files are *already*
//! deleted as far as the user is concerned; emptying the trash is the second
//! half of a decision they made. It is [`TargetRisk::Review`] rather than
//! `Safe` because it is the last moment to change their mind, and never
//! pre-ticked.
//!
//! # 3. Stale screenshots — the odd one out, and the reason for this comment
//!
//! Every other target in Sentinel is a directory named by a compile-time
//! constant. This one is *individual files the user created*, selected by a
//! rule: in `~/Pictures/Screenshots`, non-recursively, regular files only, with
//! a screenshot's file extension, older than a configured age.
//!
//! That is a genuine departure from the closed-list model in
//! `product-docs/SECURITY.md` §4, so it is fenced in on every side:
//!
//! - **One directory, not a tree.** No recursion. A subdirectory someone made
//!   inside their screenshots folder is not descended into.
//! - **Regular files only.** Not directories, not symlinks.
//! - **An extension allowlist**, so a document that happens to live there is
//!   never proposed.
//! - **An age floor.** [`MIN_RETENTION_DAYS`] applies whatever is configured,
//!   so a `0` in the settings file cannot mean "everything, including the
//!   screenshot taken a minute ago".
//! - **Never pre-ticked**, because these are the user's own files, not a cache.
//!
//! # What is deliberately *not* offered: `/tmp`
//!
//! `/tmp` is the obvious thing to expect here and this plugin will not delete
//! from it. It holds live sockets, lock files and directories belonging to
//! processes that are running right now, and deciding which of those is
//! disposable needs to know what has them open — which this plugin cannot know
//! and will not guess. [`Plugin::recommend`] explains that in the UI, and
//! [`Plugin::scan`] returns no target for it. See [`TMP_EXPLANATION`].

use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use sentinel_plugin_api::{
    directory_size, file_size, is_empty_directory, CleanFailure, CleanOutcome, CleanTarget, Plugin,
    PluginError, PluginMetadata, Recommendation, ScanResult, TargetRisk, VerifiedTarget,
};

pub mod locations;

/// This plugin's stable id. Permanent once shipped — cleanup history is keyed
/// on it, and it is also what the desktop shell matches to decide which page
/// lists this plugin.
pub const PLUGIN_ID: &str = "junk";

/// Screenshots younger than this are never offered, whatever the settings file
/// says.
///
/// The retention age is user-configurable, and a user-editable file can end up
/// holding a `0` — by a typo, or by someone assuming the units are months.
/// Without a floor that would propose every screenshot the user has, including
/// one taken a minute ago. Same reasoning as the scheduler's interval floor.
pub const MIN_RETENTION_DAYS: u32 = 7;

/// The retention age used when nothing is configured.
pub const DEFAULT_RETENTION_DAYS: u32 = 30;

/// What the UI shows about `/tmp`, in place of any target.
pub const TMP_EXPLANATION: &str =
    "Sentinel does not delete from /tmp. It holds sockets, lock files and working directories \
     belonging to programs that are running right now, and knowing which of those is safe to \
     remove means knowing what has them open. Linux already clears /tmp for you — on most \
     systems at every reboot, and otherwise on a timer.";

/// Extensions a screenshot may have. Anything else in the folder is left alone.
const SCREENSHOT_EXTENSIONS: &[&str] = &["png", "jpg", "jpeg", "webp"];

/// One directory this plugin knows how to reclaim.
struct KnownDirectory {
    /// Path components under the root, all compile-time constants.
    components: &'static [&'static str],
    /// What the user sees.
    label: &'static str,
    /// How much care removing it needs.
    risk: TargetRisk,
    /// Why it is safe, or what is lost.
    note: &'static str,
}

/// Every directory under the cache home this plugin will ever propose.
const THUMBNAIL_CACHES: &[KnownDirectory] = &[
    KnownDirectory {
        components: &["thumbnails", "normal"],
        label: "Thumbnail cache (normal)",
        risk: TargetRisk::Safe,
        note: "Small preview images your file manager generated. Regenerated the next time you \
               open the folder they came from.",
    },
    KnownDirectory {
        components: &["thumbnails", "large"],
        label: "Thumbnail cache (large)",
        risk: TargetRisk::Safe,
        note: "Larger previews, regenerated on demand.",
    },
    KnownDirectory {
        components: &["thumbnails", "x-large"],
        label: "Thumbnail cache (x-large)",
        risk: TargetRisk::Safe,
        note: "The largest preview size, regenerated on demand.",
    },
    KnownDirectory {
        components: &["thumbnails", "fail"],
        label: "Failed thumbnail records",
        risk: TargetRisk::Safe,
        note: "Markers for files a thumbnail could not be made from, kept so it isn't retried \
               every time. Harmless to remove.",
    },
];

/// Every directory under the data home this plugin will ever propose.
const TRASH_DIRECTORIES: &[KnownDirectory] = &[
    KnownDirectory {
        components: &["Trash", "files"],
        label: "Trash contents",
        risk: TargetRisk::Review,
        note: "The files themselves. You already deleted these — removing them here is the point \
               of no return, so nothing is ticked for you.",
    },
    KnownDirectory {
        components: &["Trash", "info"],
        label: "Trash records",
        risk: TargetRisk::Review,
        note: "Notes on where each trashed file came from, used by \"Restore\". Remove this \
               alongside the contents above; on its own it just loses the restore paths.",
    },
    KnownDirectory {
        components: &["Trash", "expunged"],
        label: "Trash leftovers (expunged)",
        risk: TargetRisk::Review,
        note: "Fragments left behind by an interrupted empty-trash. Nothing here is reachable \
               from the Trash folder any more.",
    },
];

/// Reclaims the machine's own disposable data — thumbnails, trash, and
/// screenshots old enough that the user has forgotten them.
///
/// Notably **not** `/tmp`; see the crate docs.
#[derive(Debug)]
pub struct JunkPlugin {
    retention_days: u32,
    /// Overrides discovery. Exists for tests, which must never touch the
    /// developer's real trash or screenshots.
    roots_override: Option<Roots>,
}

/// The three directories a scan works from.
///
/// Grouped into one type so a test can supply all three from a fixture, and so
/// the shipped path resolves all three the same way.
#[derive(Debug, Clone)]
struct Roots {
    cache_home: Option<PathBuf>,
    data_home: Option<PathBuf>,
    screenshots: Option<PathBuf>,
}

impl JunkPlugin {
    /// The plugin as it ships, with the configured screenshot retention age.
    ///
    /// The age is clamped by [`MIN_RETENTION_DAYS`] at scan time rather than
    /// here, so a caller cannot construct one that skips the floor.
    pub fn new(retention_days: u32) -> Self {
        Self {
            retention_days,
            roots_override: None,
        }
    }

    /// A plugin pinned to specific directories, for tests.
    pub fn with_roots(
        retention_days: u32,
        cache_home: Option<PathBuf>,
        data_home: Option<PathBuf>,
        screenshots: Option<PathBuf>,
    ) -> Self {
        Self {
            retention_days,
            roots_override: Some(Roots {
                cache_home,
                data_home,
                screenshots,
            }),
        }
    }

    /// The retention age actually applied, floor included.
    pub fn effective_retention_days(&self) -> u32 {
        self.retention_days.max(MIN_RETENTION_DAYS)
    }

    fn roots(&self) -> Roots {
        match &self.roots_override {
            Some(roots) => roots.clone(),
            // A source that isn't available on this machine is simply absent.
            // Unlike a single-tool plugin, "no trash directory" here does not
            // mean the whole plugin is inapplicable — the thumbnail cache may
            // still be there.
            None => Roots {
                cache_home: locations::cache_home().ok(),
                data_home: locations::data_home().ok(),
                screenshots: locations::screenshots().ok(),
            },
        }
    }

    /// Turns a closed list of known directories under a root into targets.
    fn scan_directories(
        &self,
        root: &Path,
        known: &'static [KnownDirectory],
        targets: &mut Vec<CleanTarget>,
    ) -> Result<(), PluginError> {
        for entry in known {
            // Constants joined onto a validated root. This is the only place a
            // directory path is constructed, and nothing in it is variable.
            let mut path = root.to_path_buf();
            for component in entry.components {
                path.push(component);
            }

            // `symlink_metadata` so a symlink is seen as a symlink rather than
            // as whatever it points at.
            let Ok(metadata) = std::fs::symlink_metadata(&path) else {
                continue;
            };
            if !metadata.is_dir() {
                continue;
            }
            if is_empty_directory(&path) {
                continue;
            }

            let size = directory_size(&path)?;

            targets.push(CleanTarget::new(
                PLUGIN_ID,
                path,
                format!("{} — {}", entry.label, entry.note),
                size,
                entry.risk,
            ));
        }

        Ok(())
    }

    /// Turns screenshots older than the retention age into one target each.
    ///
    /// Every rule here is a fence around the one place this plugin proposes
    /// files the user made rather than a cache — see the crate docs.
    fn scan_screenshots(
        &self,
        root: &Path,
        targets: &mut Vec<CleanTarget>,
    ) -> Result<(), PluginError> {
        let days = self.effective_retention_days();
        let cutoff = match SystemTime::now().checked_sub(Duration::from_secs(
            u64::from(days).saturating_mul(24 * 60 * 60),
        )) {
            Some(cutoff) => cutoff,
            // A clock so far from the epoch that subtracting a month
            // underflows. Propose nothing rather than guess at an age.
            None => return Ok(()),
        };

        // `read_dir`, not a walk: one directory, no recursion.
        let entries = std::fs::read_dir(root).map_err(PluginError::Io)?;

        let mut found: Vec<(PathBuf, u64, SystemTime)> = Vec::new();

        for entry in entries.flatten() {
            let path = entry.path();

            // Does not follow symlinks, so a link pointing into a photo
            // library is seen as a link and rejected below.
            let Ok(metadata) = entry.metadata() else {
                continue;
            };
            if !metadata.is_file() {
                continue;
            }

            if !has_screenshot_extension(&path) {
                continue;
            }

            let Ok(modified) = metadata.modified() else {
                // No usable timestamp means no way to judge the age, and the
                // rule *is* the age. Skip rather than assume it is old.
                continue;
            };
            if modified >= cutoff {
                continue;
            }

            found.push((path, file_size(entry.path().as_path())?, modified));
        }

        // Oldest first: if the user is going to read only the top of the list,
        // it should be the least likely thing to be wanted.
        found.sort_by(|left, right| left.2.cmp(&right.2).then_with(|| left.0.cmp(&right.0)));

        for (path, size, _) in found {
            let name = path
                .file_name()
                .map(|name| name.to_string_lossy().into_owned())
                .unwrap_or_else(|| path.display().to_string());

            targets.push(CleanTarget::new(
                PLUGIN_ID,
                path,
                format!(
                    "{name} — a screenshot more than {days} days old. This is a file you made, \
                     not a cache, so it is never ticked for you."
                ),
                size,
                TargetRisk::Review,
            ));
        }

        Ok(())
    }
}

impl Plugin for JunkPlugin {
    fn metadata(&self) -> PluginMetadata {
        PluginMetadata {
            id: PLUGIN_ID,
            name: "System junk",
            description: "Thumbnail caches, the trash, and screenshots you've long forgotten. \
                          Never /tmp.",
        }
    }

    fn scan(&self) -> Result<ScanResult, PluginError> {
        let roots = self.roots();
        let mut targets = Vec::new();

        if let Some(cache_home) = &roots.cache_home {
            self.scan_directories(cache_home, THUMBNAIL_CACHES, &mut targets)?;
        }
        if let Some(data_home) = &roots.data_home {
            self.scan_directories(data_home, TRASH_DIRECTORIES, &mut targets)?;
        }
        if let Some(screenshots) = &roots.screenshots {
            self.scan_screenshots(screenshots, &mut targets)?;
        }

        // Every source missing means this platform isn't supported, or the
        // user's home has none of these directories. Reported as "not
        // applicable" rather than as an empty success, so the UI can say why.
        if roots.cache_home.is_none() && roots.data_home.is_none() && roots.screenshots.is_none() {
            return Err(PluginError::ToolUnavailable {
                detail: "none of the thumbnail cache, trash or screenshots directories were \
                         found for this user"
                    .to_owned(),
            });
        }

        Ok(ScanResult { targets })
    }

    fn recommend(&self) -> Result<Vec<Recommendation>, PluginError> {
        let scan = self.scan()?;

        let mut recommendations = Vec::new();

        // Always present, whether or not anything was found: it explains an
        // absence the user would otherwise read as a bug. This is the only
        // route by which the /tmp reasoning reaches the screen.
        recommendations.push(Recommendation {
            title: "Temporary files in /tmp are left alone".to_owned(),
            detail: TMP_EXPLANATION.to_owned(),
            reclaimable_bytes: 0,
            risk: TargetRisk::Destructive,
        });

        let safe_bytes = total_for(&scan, TargetRisk::Safe);
        if safe_bytes > 0 {
            recommendations.push(Recommendation {
                title: format!("Thumbnail caches are using {}", human_bytes(safe_bytes)),
                detail: "Preview images your file manager generated for folders you've browsed. \
                         They come back on their own the next time you open those folders."
                    .to_owned(),
                reclaimable_bytes: safe_bytes,
                risk: TargetRisk::Safe,
            });
        }

        let review_bytes = total_for(&scan, TargetRisk::Review);
        if review_bytes > 0 {
            recommendations.push(Recommendation {
                title: format!(
                    "Trash and old screenshots are using {}",
                    human_bytes(review_bytes)
                ),
                detail: format!(
                    "Files you already deleted, plus screenshots more than {} days old. Unlike a \
                     cache, none of this comes back — so none of it is ticked for you.",
                    self.effective_retention_days()
                ),
                reclaimable_bytes: review_bytes,
                risk: TargetRisk::Review,
            });
        }

        Ok(recommendations)
    }

    fn remove_verified(
        &self,
        verified: &[VerifiedTarget<'_>],
    ) -> Result<CleanOutcome, PluginError> {
        let mut outcome = CleanOutcome::default();

        for target in verified {
            // Targets here are a mix of directories (thumbnails, trash) and
            // single files (screenshots), so the removal has to match what is
            // actually there. `symlink_metadata` rather than `metadata`: a
            // symlink is removed as a link, never followed.
            let Ok(metadata) = std::fs::symlink_metadata(target.path()) else {
                outcome.failures.push(CleanFailure {
                    label: target.label().to_owned(),
                    reason: "it could not be read, so it was not removed".to_owned(),
                });
                continue;
            };

            // Measured before removal, so this reports what was actually freed
            // rather than the scan-time estimate.
            let freed = if metadata.is_dir() {
                directory_size(target.path()).unwrap_or(0)
            } else {
                file_size(target.path()).unwrap_or(0)
            };

            let removed = if metadata.is_dir() {
                std::fs::remove_dir_all(target.path())
            } else {
                std::fs::remove_file(target.path())
            };

            match removed {
                Ok(()) => {
                    outcome.removed.push(target.label().to_owned());
                    outcome.reclaimed_bytes = outcome.reclaimed_bytes.saturating_add(freed);
                }
                Err(cause) => outcome.failures.push(CleanFailure {
                    label: target.label().to_owned(),
                    reason: cause.to_string(),
                }),
            }
        }

        Ok(outcome)
    }
}

/// Whether a path ends in one of the extensions a screenshot may have.
///
/// Case-insensitive, because `.PNG` is the same picture.
fn has_screenshot_extension(path: &Path) -> bool {
    path.extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| {
            SCREENSHOT_EXTENSIONS
                .iter()
                .any(|allowed| extension.eq_ignore_ascii_case(allowed))
        })
}

/// Total bytes in a scan at one risk level.
fn total_for(scan: &ScanResult, risk: TargetRisk) -> u64 {
    scan.targets
        .iter()
        .filter(|target| target.risk == risk)
        .fold(0u64, |sum, target| sum.saturating_add(target.size_bytes))
}

/// Formats bytes in binary units, so the figure matches `du`.
fn human_bytes(bytes: u64) -> String {
    const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];

    let mut value = bytes as f64;
    let mut unit = 0;
    while value >= 1024.0 && unit < UNITS.len() - 1 {
        value /= 1024.0;
        unit += 1;
    }

    if unit == 0 {
        format!("{bytes} {}", UNITS[0])
    } else {
        format!("{value:.1} {}", UNITS[unit])
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use sentinel_plugin_api::clean;
    use std::fs;

    fn days_ago(days: u64) -> SystemTime {
        SystemTime::now()
            .checked_sub(Duration::from_secs(days * 24 * 60 * 60))
            .expect("a date within the last few years is representable")
    }

    /// Writes a file and backdates it, so age-based rules can be tested
    /// without waiting a month.
    fn write_aged(path: &Path, bytes: usize, age_days: u64) {
        fs::write(path, vec![b'x'; bytes]).expect("write file");
        let file = fs::File::options()
            .write(true)
            .open(path)
            .expect("reopen to set time");
        file.set_modified(days_ago(age_days))
            .expect("set modified time");
    }

    struct Fixture {
        _root: tempfile::TempDir,
        cache_home: PathBuf,
        data_home: PathBuf,
        screenshots: PathBuf,
    }

    fn fixture() -> Fixture {
        let root = tempfile::tempdir().expect("temp dir");
        let cache_home = root.path().join("cache");
        let data_home = root.path().join("data");
        let screenshots = root.path().join("Pictures").join("Screenshots");

        for path in [&cache_home, &data_home, &screenshots] {
            fs::create_dir_all(path).expect("create root");
        }

        Fixture {
            _root: root,
            cache_home,
            data_home,
            screenshots,
        }
    }

    impl Fixture {
        fn plugin(&self, retention_days: u32) -> JunkPlugin {
            JunkPlugin::with_roots(
                retention_days,
                Some(self.cache_home.clone()),
                Some(self.data_home.clone()),
                Some(self.screenshots.clone()),
            )
        }

        fn with_directory(&self, root: &Path, components: &[&str], bytes: usize) -> &Self {
            let mut path = root.to_path_buf();
            for component in components {
                path.push(component);
            }
            fs::create_dir_all(&path).expect("create directory");
            fs::write(path.join("blob"), vec![b'x'; bytes]).expect("write blob");
            self
        }
    }

    #[test]
    fn thumbnail_caches_are_offered_as_safe() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 500);

        let scan = fixture.plugin(30).scan().expect("scan succeeds");

        assert_eq!(scan.targets.len(), 1);
        assert_eq!(scan.targets[0].risk, TargetRisk::Safe);
        assert!(scan.targets[0].risk.may_be_preselected());
    }

    #[test]
    fn trash_is_offered_but_never_pre_ticked() {
        let fixture = fixture();
        fixture.with_directory(&fixture.data_home, &["Trash", "files"], 500);

        let scan = fixture.plugin(30).scan().expect("scan succeeds");

        assert_eq!(scan.targets.len(), 1);
        assert_eq!(scan.targets[0].risk, TargetRisk::Review);
        assert!(
            !scan.targets[0].risk.may_be_preselected(),
            "emptying the trash is the point of no return"
        );
    }

    /// The property the screenshot rule turns on. Only a stale file with a
    /// screenshot's extension is proposed — not a recent one, not a document,
    /// not a directory, and nothing below the top level.
    #[test]
    fn only_stale_screenshots_are_proposed() {
        let fixture = fixture();
        let shots = &fixture.screenshots;

        write_aged(&shots.join("old.png"), 100, 90);
        write_aged(&shots.join("recent.png"), 100, 2);
        write_aged(&shots.join("notes.txt"), 100, 90);
        write_aged(&shots.join("archive.zip"), 100, 90);

        let nested = shots.join("keepers");
        fs::create_dir_all(&nested).expect("create subdirectory");
        write_aged(&nested.join("buried.png"), 100, 90);

        let scan = fixture.plugin(30).scan().expect("scan succeeds");

        let names: Vec<_> = scan
            .targets
            .iter()
            .filter_map(|target| target.path().file_name())
            .map(|name| name.to_string_lossy().into_owned())
            .collect();

        assert_eq!(names, vec!["old.png"], "got {names:?}");
    }

    #[test]
    fn a_screenshot_is_never_pre_ticked() {
        let fixture = fixture();
        write_aged(&fixture.screenshots.join("old.png"), 100, 90);

        let scan = fixture.plugin(30).scan().expect("scan succeeds");

        assert_eq!(scan.targets[0].risk, TargetRisk::Review);
        assert!(
            !scan.targets[0].risk.may_be_preselected(),
            "these are files the user made, not a cache"
        );
    }

    /// A `0` in the user-editable settings file must not mean "every
    /// screenshot, including the one taken a minute ago".
    #[test]
    fn the_retention_floor_survives_a_zero_in_the_settings_file() {
        let fixture = fixture();
        write_aged(&fixture.screenshots.join("yesterday.png"), 100, 1);
        write_aged(&fixture.screenshots.join("last-month.png"), 100, 40);

        let plugin = fixture.plugin(0);
        assert_eq!(plugin.effective_retention_days(), MIN_RETENTION_DAYS);

        let scan = plugin.scan().expect("scan succeeds");
        let names: Vec<_> = scan
            .targets
            .iter()
            .filter_map(|target| target.path().file_name())
            .map(|name| name.to_string_lossy().into_owned())
            .collect();

        assert_eq!(names, vec!["last-month.png"], "got {names:?}");
    }

    /// The whole point of the `/tmp` decision: it is explained, never offered.
    #[test]
    fn tmp_is_explained_but_never_a_target() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 500);
        write_aged(&fixture.screenshots.join("old.png"), 100, 90);

        let plugin = fixture.plugin(30);
        let scan = plugin.scan().expect("scan succeeds");

        // Stated as "every target came from one of the three declared roots"
        // rather than "no target is under /tmp", because the fixture itself
        // lives under /tmp — `tempfile` puts it there. The roots-based form is
        // also the stronger claim: it holds for any directory this plugin was
        // never pointed at, not just that one.
        assert!(
            scan.targets.iter().all(|target| {
                target.path().starts_with(&fixture.cache_home)
                    || target.path().starts_with(&fixture.data_home)
                    || target.path().starts_with(&fixture.screenshots)
            }),
            "a target appeared from outside the three roots the plugin was given"
        );

        let recommendations = plugin.recommend().expect("recommend succeeds");
        assert!(
            recommendations
                .iter()
                .any(|recommendation| recommendation.detail == TMP_EXPLANATION),
            "the explanation must reach the UI, since nothing else says why /tmp is absent"
        );
    }

    #[test]
    fn a_clean_removes_files_and_directories_alike() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 500);
        write_aged(&fixture.screenshots.join("old.png"), 400, 90);
        write_aged(&fixture.screenshots.join("recent.png"), 400, 1);

        let plugin = fixture.plugin(30);
        let scan = plugin.scan().expect("scan succeeds");
        assert_eq!(scan.targets.len(), 2, "one directory and one file");

        let outcome = clean(&plugin, &scan.targets).expect("clean succeeds");

        assert_eq!(outcome.removed.len(), 2);
        assert!(outcome.failures.is_empty(), "got {:?}", outcome.failures);
        assert!(outcome.reclaimed_bytes > 0);

        assert!(!fixture.screenshots.join("old.png").exists());
        assert!(
            fixture.screenshots.join("recent.png").exists(),
            "a screenshot below the age threshold must survive"
        );
        assert!(!fixture
            .cache_home
            .join("thumbnails")
            .join("normal")
            .exists());
    }

    /// A path this plugin never reported must not reach the filesystem, even
    /// carrying the right plugin id.
    #[test]
    fn a_forged_target_is_refused() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 10);

        let victim = tempfile::tempdir().expect("temp dir");
        fs::write(victim.path().join("thesis.txt"), "years of work").expect("write");

        let plugin = fixture.plugin(30);
        let forged = CleanTarget::new(PLUGIN_ID, victim.path(), "forged", 10, TargetRisk::Safe);

        let outcome = clean(&plugin, &[forged]).expect("refusal is reported, not fatal");

        assert!(outcome.removed.is_empty());
        assert!(victim.path().join("thesis.txt").exists());
    }

    #[test]
    fn a_machine_with_none_of_these_directories_reads_as_not_applicable() {
        let plugin = JunkPlugin::with_roots(30, None, None, None);

        assert!(matches!(
            plugin.scan(),
            Err(PluginError::ToolUnavailable { .. })
        ));
    }

    #[test]
    fn one_missing_source_does_not_hide_the_others() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 500);

        let plugin = JunkPlugin::with_roots(30, Some(fixture.cache_home.clone()), None, None);

        let scan = plugin.scan().expect("a missing trash is not a failure");
        assert_eq!(scan.targets.len(), 1);
    }

    #[test]
    fn nothing_to_clean_is_a_successful_empty_scan() {
        let fixture = fixture();

        let scan = fixture.plugin(30).scan().expect("scan succeeds");

        assert!(scan.targets.is_empty());
        assert_eq!(scan.total_bytes(), 0);
    }

    #[test]
    fn recommendations_never_name_a_path() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "normal"], 4096);
        write_aged(&fixture.screenshots.join("old.png"), 400, 90);

        let recommendations = fixture.plugin(30).recommend().expect("recommend succeeds");

        for recommendation in &recommendations {
            assert!(!recommendation
                .detail
                .contains(fixture.cache_home.to_string_lossy().as_ref()));
        }
    }

    #[test]
    fn estimate_matches_the_scan() {
        let fixture = fixture();
        fixture.with_directory(&fixture.cache_home, &["thumbnails", "large"], 300);

        let plugin = fixture.plugin(30);
        let scan = plugin.scan().expect("scan succeeds");
        let estimate = plugin.estimate().expect("estimate succeeds");

        assert_eq!(estimate.reclaimable_bytes, scan.total_bytes());
        assert_eq!(estimate.target_count, scan.targets.len());
    }

    #[test]
    fn extension_matching_ignores_case() {
        assert!(has_screenshot_extension(Path::new("a.PNG")));
        assert!(has_screenshot_extension(Path::new("a.jpeg")));
        assert!(!has_screenshot_extension(Path::new("a.txt")));
        assert!(!has_screenshot_extension(Path::new("no-extension")));
    }

    /// Reads this machine's real junk directories, read-only. Ignored by
    /// default.
    #[test]
    #[ignore = "reads the developer's real trash and screenshots; run manually"]
    fn scans_the_real_machine() {
        let plugin = JunkPlugin::new(DEFAULT_RETENTION_DAYS);

        match plugin.scan() {
            Ok(scan) => {
                for target in &scan.targets {
                    println!(
                        "  {:>10}  {:?}  {}",
                        human_bytes(target.size_bytes),
                        target.risk,
                        target.path().display()
                    );
                }
                println!("  total: {}", human_bytes(scan.total_bytes()));
            }
            Err(PluginError::ToolUnavailable { detail }) => {
                println!("  not applicable here: {detail}");
            }
            Err(other) => panic!("unexpected scan failure: {other}"),
        }
    }
}
